+
+    let formData = { ...initialFormState };
+    let touched = {};
+    let submitted = false;
+    let wasSuccessful = false;
+
+    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    const phoneCharactersPattern = /^\+?[0-9\s().-]+$/;
