+        wasSuccessful = Object.keys(errors).length === 0;
+        render();
+
+        if (!wasSuccessful) {
+          const firstInvalidField = formFields.find((field) => errors[field.id]);
+          document.getElementById(firstInvalidField.id).focus();
+        }
+      });
+    }
+
+    render();
+  </script>
+</body>
+</html>
