<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: #080b12;
      color: #f7f8fb;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      background:
        radial-gradient(circle at top left, rgba(99, 102, 241, 0.28), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 28rem),
        #080b12;
    }

    .support-card {
      width: min(100%, 520px);
      padding: 34px;
      border: 1px solid rgba(148, 163, 184, 0.18);
      border-radius: 24px;
      background: rgba(15, 23, 42, 0.82);
      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      backdrop-filter: blur(20px);
    }

    .eyebrow {
      margin: 0 0 10px;
      color: #93c5fd;
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 7vw, 3rem);
      line-height: 1;
      letter-spacing: -0.05em;
    }

    .intro {
      margin: 14px 0 28px;
      color: #a7b0c2;
      line-height: 1.6;
    }

    .form-field {
      margin-bottom: 20px;
    }

    label {
      display: block;
      margin-bottom: 8px;
      color: #e5e7eb;
      font-size: 0.95rem;
      font-weight: 650;
    }

    input {
      width: 100%;
      min-height: 48px;
      padding: 12px 14px;
      border: 1px solid #334155;
      border-radius: 14px;
      outline: none;
      background: rgba(2, 6, 23, 0.72);
      color: #f8fafc;
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: #60a5fa;
      background: rgba(15, 23, 42, 0.95);
      box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.18);
    }

    input[aria-invalid="true"] {
      border-color: #fb7185;
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
    }

    .helper-text,
    .validation-message {
      margin: 7px 0 0;
      font-size: 0.86rem;
      line-height: 1.4;
    }

    .helper-text {
      color: #94a3b8;
    }

    .validation-message {
      color: #fda4af;
      font-weight: 650;
    }

    button {
      width: 100%;
      min-height: 52px;
      margin-top: 6px;
      border: 0;
      border-radius: 16px;
      background: linear-gradient(135deg, #60a5fa, #818cf8);
      color: #06111f;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      letter-spacing: -0.01em;
      box-shadow: 0 18px 34px rgba(96, 165, 250, 0.22);
      transition: transform 160ms ease, filter 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    .success-message {
      margin: 18px 0 0;
      padding: 12px 14px;
      border: 1px solid rgba(52, 211, 153, 0.28);
      border-radius: 14px;
      background: rgba(6, 78, 59, 0.25);
      color: #a7f3d0;
      font-weight: 650;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 520px) {
      .support-card {
        padding: 26px 20px;
      }
    }
  </style>
</head>
<body>
  <main id="root">
    <section class="support-card" aria-labelledby="support-title">
      <p class="eyebrow">Support request</p>
      <h1 id="support-title">Contact support</h1>
      <p class="intro">Tell us how to reach you and our support team will follow up shortly.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="fullName">Full name *</label>
          <input
            id="fullName"
            name="fullName"
            type="text"
            placeholder="Ada Lovelace"
            autocomplete="name"
            required
            aria-invalid="false"
            aria-describedby="fullName-error"
          >
          <p class="validation-message" id="fullName-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="email">Email address *</label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="ada@example.com"
            autocomplete="email"
            required
            aria-invalid="false"
            aria-describedby="email-error"
          >
          <p class="validation-message" id="email-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            placeholder="+1 555 123 4567"
            autocomplete="tel"
            aria-invalid="false"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Optional. Use digits, spaces, dashes, parentheses, or a leading plus sign; 7 to 15 digits total.</p>
          <p class="validation-message" id="phone-error" hidden></p>
        </div>

        <button type="submit">Submit request</button>
      </form>

      <p class="success-message" id="success-message" role="status" hidden></p>
    </section>
  </main>

  <script>
    const SupportContactForm = {
      fields: [
        { id: "fullName", requiredMessage: "Full name is required." },
        { id: "email", requiredMessage: "Email address is required." },
        { id: "phone" }
      ],
      emailPattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
      phoneCharactersPattern: /^\+?[0-9\s().-]+$/,

      init() {
        this.form = document.getElementById("support-form");
        this.successMessage = document.getElementById("success-message");

        this.fields.forEach((field) => {
          const input = document.getElementById(field.id);
          input.addEventListener("blur", () => this.validateField(field.id));
          input.addEventListener("input", () => {
            this.successMessage.hidden = true;
            if (input.getAttribute("aria-invalid") === "true") {
              this.validateField(field.id);
            }
          });
        });

        this.form.addEventListener("submit", (event) => this.handleSubmit(event));
      },

      getValues() {
        return this.fields.reduce((values, field) => {
          values[field.id] = document.getElementById(field.id).value.trim();
          return values;
        }, {});
      },

      validate(values = this.getValues()) {
        const errors = {};

        if (!values.fullName) {
          errors.fullName = "Full name is required.";
        }

        if (!values.email) {
          errors.email = "Email address is required.";
        } else if (!this.emailPattern.test(values.email)) {
          errors.email = "Enter a valid email address.";
        }

        if (values.phone) {
          const digitCount = values.phone.replace(/\D/g, "").length;

          if (!this.phoneCharactersPattern.test(values.phone) || digitCount < 7 || digitCount > 15) {
            errors.phone = "Enter a valid phone number in the expected format.";
          }
        }

        return errors;
      },

      validateField(fieldId) {
        const errors = this.validate();
        this.showFieldError(fieldId, errors[fieldId]);
        return !errors[fieldId];
      },

      showFieldError(fieldId, message) {
        const input = document.getElementById(fieldId);
        const error = document.getElementById(`${fieldId}-error`);

        input.setAttribute("aria-invalid", message ? "true" : "false");
        error.textContent = message || "";
        error.hidden = !message;
      },

      handleSubmit(event) {
        event.preventDefault();

        const values = this.getValues();
        const errors = this.validate(values);

        this.fields.forEach((field) => {
          this.showFieldError(field.id, errors[field.id]);
        });

        if (Object.keys(errors).length > 0) {
          const firstInvalidField = this.fields.find((field) => errors[field.id]);
          document.getElementById(firstInvalidField.id).focus();
          this.successMessage.hidden = true;
          return;
        }

        this.successMessage.textContent = `Thanks, ${values.fullName}. Your request is ready to send.`;
        this.successMessage.hidden = false;
      }
    };

    SupportContactForm.init();
  </script>
</body>
</html>
